class C:
 def __getattribute__(self,name):
  print(name)
  if name=="__name__": raise AttributeError("absent")
  return [name]
w=staticmethod(C())
print(w.__module__[0],hasattr(w,"__name__"),w.__doc__[0])

class C:
 def __getattribute__(self,name):
  print(name)
  if name=="__qualname__": raise ValueError("stop")
  return name
staticmethod(C())

